@Injectable({ providedIn: 'root' })
export class TodoStore {
  private readonly state = signal({ todos: [] as Todo[], filter: 'all' as Filter });

  readonly todos = computed(() => this.state().todos);
  readonly visible = computed(() => {
    const { todos, filter } = this.state();
    return filter === 'all' ? todos : todos.filter(t => t.done === (filter === 'done'));
  });

  setFilter(filter: Filter) { this.state.update(s => ({ ...s, filter })); }
}

export const TodoStore = signalStore(
  { providedIn: 'root' },
  withState({ todos: [] as Todo[], loading: false }),
  withComputed(({ todos }) => ({
    doneCount: computed(() => todos().filter(t => t.done).length),
  })),
  withMethods((store) => ({
    add(todo: Todo) { patchState(store, { todos: [...store.todos(), todo] }); },
  })),
);

